package popcount

import "math/bits"

// Popcount returns the number of set bits across all words of xs.
func Popcount(xs []uint64) int {
	const (
		m1 = 0x5555555555555555
		m2 = 0x3333333333333333
		m4 = 0x0f0f0f0f0f0f0f0f
		h  = 0x0101010101010101
	)
	n := 0
	for len(xs) >= 8 {
		a, b, c, d := xs[0], xs[1], xs[2], xs[3]
		e, f, g, k := xs[4], xs[5], xs[6], xs[7]
		a -= a >> 1 & m1
		b -= b >> 1 & m1
		c -= c >> 1 & m1
		d -= d >> 1 & m1
		e -= e >> 1 & m1
		f -= f >> 1 & m1
		g -= g >> 1 & m1
		k -= k >> 1 & m1
		a = a&m2 + a>>2&m2
		b = b&m2 + b>>2&m2
		c = c&m2 + c>>2&m2
		d = d&m2 + d>>2&m2
		e = e&m2 + e>>2&m2
		f = f&m2 + f>>2&m2
		g = g&m2 + g>>2&m2
		k = k&m2 + k>>2&m2
		// nibble counts <=4 each; pair sums <=8 still fit a nibble
		a += b
		c += d
		e += f
		g += k
		a = a&m4 + a>>4&m4
		c = c&m4 + c>>4&m4
		e = e&m4 + e>>4&m4
		g = g&m4 + g>>4&m4
		// byte counts <=16 each; sum of four <=64
		a += c + e + g
		n += int((a * h) >> 56)
		xs = xs[8:]
	}
	for _, x := range xs {
		n += bits.OnesCount64(x)
	}
	return n
